import { createElement } from '../../vendor/react.js';

export function Button({
  variant = 'secondary',
  disabled = false,
  children = '',
} = {}) {
  const kind = variant === 'primary' ? 'primary' : 'secondary';
  return createElement(
    'button',
    {
      type: 'button',
      className: `btn btn-${kind}`,
      disabled: Boolean(disabled),
    },
    children,
  );
}
import { createElement } from '../../vendor/react.js';

export function Toolbar() {
  return createElement(
    'nav',
    { className: 'toolbar' },
    createElement('span', { className: 'doc-title' }, 'Untitled'),
    createElement('button', { type: 'button', className: 'ghost' }, 'Cancel'),
  );
}
export function createElement(type, props, ...children) {
  return {
    type,
    props: props || {},
    children: children.flat().filter((child) => child !== null && child !== undefined),
  };
}

export default { createElement };
